/* GENERATED by scripts/sync-bichos.mjs from the avatar lab's styles/bichos.ts: do not edit.
 * What every figure shares: the mascot frame and the CSS (moods, sizes, shared groups), with the third-party mascots'
 * rules left out. The lab's seed-to-mascot lookup (its `bichos` style object) is left out too: a mascot is drawn only
 * when asked for by name (renderMascot), never because a seed spells one. src/styles/bichos.css is built from `CSS`. */

export { renderSpec } from "../bichos/render";
export { normalizeSpec } from "../bichos/spec";
export { specFromSeed } from "../bichos/seed";
export type { Spec } from "../bichos/kit";

/** A mascot's cues go beside its mark the way a bicho's go beside its silhouette: from the mark's hull (mascots.ts). */
export function renderMascot(kind: Harness, size: Size): Drawn {
  const m = mascot(kind, uid("bx"));
  const spots = spotsOf(profileOf([{ loops: flatten(m.hull ?? "M30 30H90V106H30Z"), r: 0 }]), m.eyeY ?? 58, size);
  const html = `<svg viewBox="0 0 120 120" aria-hidden="true" data-kind="${kind}" data-logo>
      <defs>${m.defs}</defs>
      <ellipse class="ground" cx="60" cy="110" rx="26" ry="4"/>
      <g class="fig"><g class="squash">
        ${m.body}
        ${m.shine ? `<path class="shine" d="${m.shine}"/>` : ""}
        <g class="eyes">${m.eyes}</g><g class="eyes-closed">${m.closed}</g>
        <g class="m-rest">${m.mouthRest}</g><g class="m-open">${m.mouthOpen}</g>
      </g></g>
      ${props(spots, size)}
    </svg>`;
  return { html, traits: m.traits, tone: m.tone };
}

