/** "waiting" (your turn) is the app's older mood for idle, and renders exactly like it: every rule keyed on idle
 * matches waiting too, and the old waiting-only rules (part files written for the bouncy waiting) are retired. Applied
 * to all the style's CSS, the part files' included, so a new idle rule anywhere covers waiting with no extra work. */
function aliasWaiting(css: string): string {
  return css.replace(/\[data-mood=waiting\]/g, ":not(*)").replace(/\[data-mood=idle\]/g, ":is([data-mood=idle], [data-mood=waiting])");
}

/** How long the client keeps `data-enter` on the root after a mood change that makes an entrance (the startle's length). */
export const ENTER_MS = 420;
/** The `data-enter` value for a change of mood: the mood it leaves when the new one makes an entrance (listening, from
 * idle, waiting or working), or null. While it is set, keep the old mood's `data-work` (or `data-idle`) on the root
 * too, so what the bicho had in hand can drop away; drop both after ENTER_MS. */
export function enterFrom(prev: string | null | undefined, next: string): "idle" | "working" | null {
  if (next !== "listening") return null;
  if (prev === "working") return "working";
  return prev === "idle" || prev === "waiting" ? "idle" : null;
}

export const CSS = aliasWaiting(BASE_CSS + PARTS_CSS + IDLE_CSS);
